<script lang="ts">
  import { onMount } from "svelte";
  import { ArchiveX, BookOpenText, Eye, FolderGit2, GitBranch, Lock, Pencil, Plus, RefreshCw, Save, Trash2, X } from "@lucide/svelte";
  import { isUiLockedProject, isUiLockedWorkspace, workspacesForHost } from "./workspace-management";
  import { t } from "./i18n";
  export let api:(path:string,init?:RequestInit)=>Promise<any>;
  export let projects:Array<{id:string;name:string;slug?:string;description?:string|null;enabled:boolean;archivedAt?:string|null}>=[];
  type Host={id:string;type:"local"|"worker";displayName:string;platform:string;architecture:string;status:string};
  type Root={id:string;hostId?:string;displayName:string;canonicalPath?:string;allowCreate:boolean;allowRegister:boolean;allowClone:boolean;allowDelete?:boolean;disabledAt?:string|null};
  type Workspace={id:string;projectId:string;hostId:string;rootId:string;displayName:string;canonicalPath:string;workspaceType:string;lastGitStatus?:any};
  export let onviewworkspace:(workspace:Workspace)=>void=()=>{};
  let hosts:Host[]=[],workspaces:Workspace[]=[],roots:Root[]=[],selectedHost="local",loading=false,notice="";
  let createOpen=false,projectId="",rootId="",mode:"existing"|"empty"|"git-init"|"git-clone"="empty",folderName="",displayName="",repository="",defaultBranch="main",cloneBranch="",shallow=false,readme=true,browse:any=null,selectedEntry="",githubRepos:any[]=[],githubSearch="";
  let newProjectOpen=false,newProjectName="",newProjectSlug="",newProjectDescription="";
  let editingProjectId="",editProjectName="",editProjectDescription="",editProjectWorkspaceIds:string[]=[],projectPipelineLoading=false,editingWorkspaceId="",editWorkspaceName="",editWorkspaceRootId="",editWorkspacePath="",pathBrowse:any=null;
  let instructionWorkspace:Workspace|null=null,instructionLoading=false,instructionRepository:Array<{name:string;digest:string}>=[],instructionProfile:any={version:1,enabled:false,sourceMode:"combined",markdown:"",agentEditable:false,lastEditedBy:"owner",lastEditedTaskId:null,revision:0,completionPolicy:{restart:"runtime-change",requireCheck:true,requireTest:true,requireBuild:true,requireDirectVerification:true,execution:"instruct"}};
  let selectedHostRecord:Host|undefined,selectedHostWorkspaces:Workspace[]=[];
  $: selectedHostRecord=hosts.find(item=>item.id===selectedHost);
  $: selectedHostWorkspaces=workspacesForHost(workspaces,selectedHost);
  const systemProject=isUiLockedProject;
  const systemWorkspace=isUiLockedWorkspace;
  async function load(){loading=true;notice="";try{const [h,w,p]=await Promise.all([api("/api/hosts"),api("/api/workspaces"),api("/api/projects")]);hosts=h.hosts??[];workspaces=w.workspaces??[];projects=p.projects??projects;if(!hosts.some(item=>item.id===selectedHost))selectedHost=hosts[0]?.id??"local";await loadRoots();if(!projects.some(item=>item.id===projectId&&item.enabled&&!systemProject(item)))projectId=projects.find(item=>item.enabled&&!systemProject(item))?.id??"";}catch(error){notice=error instanceof Error?error.message:String(error)}finally{loading=false;}}
  async function loadRoots(){if(!selectedHost)return;try{roots=((await api(`/api/workspace-roots?hostId=${encodeURIComponent(selectedHost)}`)).roots??[]).filter((item:Root)=>!item.disabledAt);if(!roots.some(item=>item.id===rootId))rootId=roots[0]?.id??"";}catch(error){roots=[];notice=error instanceof Error?error.message:String(error)}}
  async function chooseHost(id:string){selectedHost=id;createOpen=false;browse=null;pathBrowse=null;await loadRoots();}
  async function createWorkspace(){if(!projectId||!rootId||!folderName)return;loading=true;notice="";try{const common={hostId:selectedHost,projectId,rootId,folderName,displayName:displayName||undefined};if(mode==="git-clone")await api("/api/workspaces/clone",{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({...common,repository,branch:cloneBranch||undefined,shallow})});else await api("/api/workspaces/create",{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({...common,mode,readme,defaultBranch})});createOpen=false;folderName="";displayName="";repository="";cloneBranch="";shallow=false;await load();}catch(error){notice=error instanceof Error?error.message:String(error)}finally{loading=false;}}
  async function loadGitHubRepos(){try{const params=new URLSearchParams({search:githubSearch,visibility:"all",limit:"100"});githubRepos=(await api(`/api/hosts/${encodeURIComponent(selectedHost)}/github/repositories?${params}`)).repositories??[];}catch(error){notice=error instanceof Error?error.message:String(error)}}
  function chooseRepo(repo:any){repository=repo.httpsUrl??repo.sshUrl??"";cloneBranch=repo.defaultBranch??"";folderName=folderName||repo.name;displayName=displayName||repo.name;}
  async function browseRoot(entryId?:string){try{const params=new URLSearchParams({hostId:selectedHost});if(entryId)params.set("entryId",entryId);browse=await api(`/api/workspace-roots/${rootId}/browse?${params}`);selectedEntry=browse.current?.id??"";}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function submitWorkspace(){if(mode!=="existing")return createWorkspace();if(!projectId||!rootId||!selectedEntry)return;loading=true;try{await api("/api/workspaces/register",{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({hostId:selectedHost,projectId,rootId,entryId:selectedEntry,displayName:displayName||undefined})});createOpen=false;browse=null;await load();}catch(error){notice=error instanceof Error?error.message:String(error)}finally{loading=false;}}
  async function refreshGit(item:Workspace){try{item.lastGitStatus=(await api(`/api/workspaces/${item.id}/git-status`)).status;workspaces=[...workspaces];}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function unregisterWorkspace(item:Workspace){if(systemWorkspace(item)||!confirm($t("host.workspaceUnregisterConfirm",{name:item.displayName})))return;try{await api(`/api/workspaces/${item.id}/unregister`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({confirm:true,filesRemain:true})});await load();notice=$t("host.workspaceUnregistered");}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function createWorktree(item:Workspace){const folderName=prompt($t("host.worktreeFolderName"),`${item.displayName.replace(/[^A-Za-z0-9._ -]/g,"-")}-worktree`)?.trim();if(!folderName)return;const branch=prompt($t("host.worktreeBranch"),"")?.trim()||undefined;try{await api(`/api/workspaces/${item.id}/worktree`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({folderName,displayName:`${item.displayName} · ${$t("host.isolated")}`,branch})});notice=$t("host.worktreeCreated");await load();}catch(error){notice=error instanceof Error?error.message:String(error)}}
  const projectSlugUnavailable=()=>newProjectSlug==="claudex-workhouse"||projects.some(item=>item.id===newProjectSlug);
  async function createProject(){if(!newProjectName||!newProjectSlug||projectSlugUnavailable()){notice=$t("host.slugUnavailable");return;}try{const data=await api("/api/projects",{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({name:newProjectName,slug:newProjectSlug,description:newProjectDescription||null})});projects=[...projects,{...data.project,enabled:true}];projectId=data.project.id;newProjectOpen=false;newProjectName="";newProjectSlug="";newProjectDescription="";}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function beginProjectEdit(item:(typeof projects)[number]){if(systemProject(item))return;editingProjectId=item.id;editProjectName=item.name;editProjectDescription=item.description??"";projectPipelineLoading=true;try{const data=await api(`/api/projects/${encodeURIComponent(item.id)}/workspace-pipeline`);editProjectWorkspaceIds=data.workspaceIds??[];}catch(error){notice=error instanceof Error?error.message:String(error);editProjectWorkspaceIds=[];}finally{projectPipelineLoading=false;}}
  function cancelProjectEdit(){editingProjectId="";editProjectName="";editProjectDescription="";editProjectWorkspaceIds=[];}
  function togglePipelineWorkspace(id:string){editProjectWorkspaceIds=editProjectWorkspaceIds.includes(id)?editProjectWorkspaceIds.filter(item=>item!==id):[...editProjectWorkspaceIds,id];}
  function movePipelineWorkspace(id:string,direction:-1|1){const index=editProjectWorkspaceIds.indexOf(id),next=index+direction;if(index<0||next<0||next>=editProjectWorkspaceIds.length)return;const reordered=[...editProjectWorkspaceIds];[reordered[index],reordered[next]]=[reordered[next],reordered[index]];editProjectWorkspaceIds=reordered;}
  async function saveProject(item:(typeof projects)[number]){if(systemProject(item)||!editProjectName.trim())return;try{await api(`/api/projects/${encodeURIComponent(item.id)}`,{method:"PATCH",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({name:editProjectName,description:editProjectDescription||null,workspaceIds:editProjectWorkspaceIds})});cancelProjectEdit();notice=$t("host.projectUpdated");await load();}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function archiveProject(item:(typeof projects)[number]){if(systemProject(item)||!confirm($t("host.projectArchiveConfirm",{name:item.name})))return;try{await api(`/api/projects/${encodeURIComponent(item.id)}/archive`,{method:"POST",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({confirm:true,filesRemain:true})});notice=$t("host.projectArchived");await load();}catch(error){notice=error instanceof Error?error.message:String(error)}}
  function beginWorkspaceEdit(item:Workspace){if(systemWorkspace(item))return;editingWorkspaceId=item.id;editWorkspaceName=item.displayName;editWorkspaceRootId=item.rootId;editWorkspacePath=item.canonicalPath;pathBrowse=null;}
  function cancelWorkspaceEdit(){editingWorkspaceId="";editWorkspaceName="";editWorkspaceRootId="";editWorkspacePath="";pathBrowse=null;}
  function browsedCanonicalPath(){const base=roots.find(item=>item.id===editWorkspaceRootId)?.canonicalPath,relative=pathBrowse?.current?.relativePath;if(!base||typeof relative!=="string")return"";return relative==="."?base:`${base.replace(/[\\/]$/,"")}/${relative}`;}
  async function browseWorkspacePath(entryId?:string){if(!editWorkspaceRootId)return;try{const params=new URLSearchParams({hostId:selectedHost});if(entryId)params.set("entryId",entryId);pathBrowse=await api(`/api/workspace-roots/${encodeURIComponent(editWorkspaceRootId)}/browse?${params}`);}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function saveWorkspace(item:Workspace){if(systemWorkspace(item)||!editWorkspaceName.trim()||!editWorkspacePath.trim())return;const pathChanged=editWorkspacePath.trim()!==item.canonicalPath||editWorkspaceRootId!==item.rootId;if(pathChanged&&!confirm($t("host.workspacePathChangeConfirm")))return;try{await api(`/api/workspaces/${encodeURIComponent(item.id)}`,{method:"PATCH",headers:{"Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({displayName:editWorkspaceName,rootId:editWorkspaceRootId,canonicalPath:editWorkspacePath,confirmPathChange:true})});cancelWorkspaceEdit();notice=$t(pathChanged?"host.workspacePathUpdated":"host.workspaceNameUpdated");await load();}catch(error){notice=error instanceof Error?error.message:String(error)}}
  async function editInstructions(item:Workspace){if(instructionWorkspace?.id===item.id){instructionWorkspace=null;return;}instructionWorkspace=item;instructionLoading=true;notice="";try{const result=await api(`/api/workspaces/${encodeURIComponent(item.id)}/instructions`);instructionProfile=structuredClone(result.profile);instructionRepository=result.repository??[];}catch(error){notice=error instanceof Error?error.message:String(error);instructionWorkspace=null;}finally{instructionLoading=false;}}
  async function saveInstructions(){if(!instructionWorkspace||instructionLoading)return;instructionLoading=true;notice="";try{const result=await api(`/api/workspaces/${encodeURIComponent(instructionWorkspace.id)}/instructions`,{method:"PUT",body:JSON.stringify({profile:instructionProfile,expectedRevision:instructionProfile.revision})});instructionProfile=structuredClone(result.profile);notice=$t("workspace.instructionsSaved");}catch(error){notice=error instanceof Error?error.message:String(error)}finally{instructionLoading=false;}}
  function submitProjectForm(event:SubmitEvent){event.preventDefault();void createProject();}
  function suggestProjectSlug(){if(!newProjectSlug)newProjectSlug=newProjectName.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,80);}
  onMount(()=>{void load();});
</script>

<section class="host-settings" aria-labelledby="workspace-settings-title">
  <div class="section-heading workspace-context-heading"><span><h3 id="workspace-settings-title">{$t("settings.workspace")}</h3><small>{$t("workspace.managementBody")}</small></span></div>
  <label class="host-selector"><span>{$t("workspace.executionLocation")}</span><select value={selectedHost} onchange={(event)=>chooseHost((event.currentTarget as HTMLSelectElement).value)}>{#each hosts as item}<option value={item.id}>{item.displayName} · {item.platform} · {$t(`status.${item.status}`)}</option>{/each}</select></label>
  <div class="section-heading project-heading"><span><h3>{$t("host.projects")}</h3><small>{$t("host.projectsBody")}</small></span><button type="button" class="new-project-toggle" onclick={()=>newProjectOpen=!newProjectOpen}><Plus size={14}/>{$t("host.newProject")}</button></div>
  {#if newProjectOpen}<form class="project-form" onsubmit={submitProjectForm}><label>{$t("common.name")}<input bind:value={newProjectName} maxlength="100" oninput={suggestProjectSlug}/></label><label>{$t("host.slug")}<input bind:value={newProjectSlug} pattern="[a-z0-9][a-z0-9-]*" maxlength="80" aria-invalid={projectSlugUnavailable()}/>{#if projectSlugUnavailable()}<small class="field-error">{$t("host.slugUnavailable")}</small>{/if}</label><label class="wide">{$t("common.description")}<input bind:value={newProjectDescription} maxlength="1000"/></label><button class="primary" disabled={!newProjectName||!newProjectSlug||projectSlugUnavailable()}>{$t("host.createProject")}</button></form>{/if}
  <div class="project-list">
    {#each projects.filter(item=>item.enabled) as item}
      <article class:system-item={systemProject(item)}>
        {#if editingProjectId===item.id}
          <div class="inline-edit project-edit"><label>{$t("common.name")}<input bind:value={editProjectName} maxlength="100"/></label><label>{$t("common.description")}<input bind:value={editProjectDescription} maxlength="1000"/></label><div class="pipeline-editor"><strong>{$t("host.workspacePipeline")}</strong><small>{$t("host.workspacePipelineBody")}</small>{#if projectPipelineLoading}<em>{$t("common.loading")}</em>{:else}{#each workspaces.filter(workspace=>workspace.projectId===item.id) as workspace}<div class:selected={editProjectWorkspaceIds.includes(workspace.id)}><label><input type="checkbox" checked={editProjectWorkspaceIds.includes(workspace.id)} onchange={()=>togglePipelineWorkspace(workspace.id)}/><span><strong>{workspace.displayName}</strong><small>{hosts.find(host=>host.id===workspace.hostId)?.displayName??workspace.hostId} · {workspace.canonicalPath}</small></span></label>{#if editProjectWorkspaceIds.includes(workspace.id)}<span class="pipeline-order"><button type="button" onclick={()=>movePipelineWorkspace(workspace.id,-1)} disabled={editProjectWorkspaceIds[0]===workspace.id} aria-label={$t("host.moveUp",{name:workspace.displayName})}>↑</button><button type="button" onclick={()=>movePipelineWorkspace(workspace.id,1)} disabled={editProjectWorkspaceIds.at(-1)===workspace.id} aria-label={$t("host.moveDown",{name:workspace.displayName})}>↓</button><em>{editProjectWorkspaceIds.indexOf(workspace.id)+1}</em></span>{/if}</div>{/each}{#if !workspaces.some(workspace=>workspace.projectId===item.id)}<em>{$t("host.noPipelineWorkspace")}</em>{/if}{/if}</div></div>
          <div class="project-actions"><button type="button" class="primary" onclick={()=>saveProject(item)} disabled={!editProjectName.trim()} aria-label={$t("common.save")}><Save size={15}/></button><button type="button" onclick={cancelProjectEdit} aria-label={$t("common.cancel")}><X size={15}/></button></div>
        {:else}
          <span><strong>{item.name}</strong><small>{item.description||item.id}</small></span>
          {#if systemProject(item)}<em class="system-badge"><Lock size={13}/>{$t("host.systemLocked")}</em>{:else}<div class="project-actions"><button type="button" onclick={()=>beginProjectEdit(item)} aria-label={$t("host.editNamed",{name:item.name})}><Pencil size={15}/></button><button type="button" class="danger-lite" onclick={()=>archiveProject(item)} aria-label={$t("host.removeNamed",{name:item.name})}><Trash2 size={15}/></button></div>{/if}
        {/if}
      </article>
    {/each}
  </div>

  <div class="section-heading workspace-heading"><span><h3>{$t("nav.workspaces")}</h3><small>{selectedHostRecord?.displayName??selectedHost} · {$t("host.registeredCount",{count:selectedHostWorkspaces.length})}</small></span><button type="button" disabled={!roots.length||selectedHostRecord?.status!=="online"||!projects.some(item=>item.enabled&&!systemProject(item))} onclick={()=>{createOpen=!createOpen;if(systemProject({id:projectId}))projectId=projects.find(item=>item.enabled&&!systemProject(item))?.id??"";}}><FolderGit2 size={15}/>{$t("host.newWorkspace")}</button></div>
  {#if createOpen}<form class="workspace-form" onsubmit={(event)=>{event.preventDefault();void submitWorkspace();}}>
    <label>{$t("session.project")}<select bind:value={projectId}>{#each projects.filter(item=>item.enabled&&!systemProject(item)) as item}<option value={item.id}>{item.name}</option>{/each}</select></label>
    <label>{$t("host.root")}<select bind:value={rootId} onchange={()=>{browse=null;if(mode==="existing")void browseRoot();}}>{#each roots as item}<option value={item.id}>{item.displayName}</option>{/each}</select></label>
    <label>{$t("host.creationMethod")}<select bind:value={mode} onchange={()=>{if(mode==="existing")void browseRoot();if(mode==="git-clone")void loadGitHubRepos();}}><option value="existing">{$t("host.creation.existing")}</option><option value="empty">{$t("host.creation.empty")}</option><option value="git-init">{$t("git.init")}</option><option value="git-clone">{$t("host.creation.clone")}</option></select></label>
    {#if mode!=="existing"}<label>{$t("host.folderName")}<input bind:value={folderName} maxlength="80" autocomplete="off"/></label>{/if}<label>{$t("host.displayName")}<input bind:value={displayName} maxlength="100"/></label>
    {#if mode==="existing"}<div class="directory-browser wide"><div><strong>{$t("host.selectFolder")}</strong><button type="button" onclick={()=>browseRoot()}>{$t("host.toRoot")}</button></div>{#if browse}<button type="button" class="current-dir" onclick={()=>selectedEntry=browse.current.id}>{$t("host.currentFolder")} · {browse.current.relativePath??"."}</button>{#each browse.entries??[] as entry}<button type="button" class:selected={selectedEntry===entry.id} onclick={()=>{selectedEntry=entry.id;void browseRoot(entry.id);}}>📁 {entry.name}</button>{/each}{:else}<button type="button" onclick={()=>browseRoot()}>{$t("host.loadFolder")}</button>{/if}</div>{/if}
    {#if mode==="git-clone"}<div class="github-picker wide"><div><input type="search" bind:value={githubSearch} placeholder={$t("host.searchGitHub")}/><button type="button" onclick={loadGitHubRepos}>{$t("host.githubList")}</button></div>{#if githubRepos.length}<select aria-label={$t("host.githubRepository")} onchange={(event)=>{const repo=githubRepos.find(item=>item.nameWithOwner===(event.currentTarget as HTMLSelectElement).value);if(repo)chooseRepo(repo);}}><option value="">{$t("host.selectRepository")}</option>{#each githubRepos as repo}<option value={repo.nameWithOwner}>{repo.nameWithOwner}{repo.private?` · ${$t("git.private")}`:""}</option>{/each}</select>{/if}</div><label class="wide">{$t("host.gitUrl")}<input bind:value={repository} maxlength="2048" inputmode="url" placeholder={$t("host.gitUrlPlaceholder")}/></label><label>{$t("host.optionalBranch")}<input bind:value={cloneBranch} maxlength="200"/></label><label class="check"><input type="checkbox" bind:checked={shallow}/>{$t("host.shallowClone")}</label>{:else if mode==="git-init"}<label>{$t("host.defaultBranch")}<input bind:value={defaultBranch} maxlength="100"/></label>{/if}
    {#if mode!=="git-clone"&&mode!=="existing"}<label class="check"><input type="checkbox" bind:checked={readme}/>{$t("host.createReadme")}</label>{/if}<button class="primary" disabled={loading||!rootId||!projectId||(mode==="existing"?!selectedEntry:!folderName)}>{loading?$t("host.processing"):mode==="existing"?$t("host.register"):$t("common.create")}</button>
  </form>{/if}
  <div class="workspace-project-summary">{#each projects.filter(project=>project.enabled) as project}<span class:missing={!selectedHostWorkspaces.some(workspace=>workspace.projectId===project.id)}><strong>{project.name}</strong> {selectedHostWorkspaces.filter(workspace=>workspace.projectId===project.id).length}{$t("host.countSuffix")}</span>{/each}</div>
  <div class="workspace-list">{#each selectedHostWorkspaces as item}<article class:system-item={systemWorkspace(item)} class:editing={editingWorkspaceId===item.id}><FolderGit2 size={18}/>{#if editingWorkspaceId===item.id}<div class="inline-edit workspace-edit"><label>{$t("host.displayName")}<input bind:value={editWorkspaceName} maxlength="100"/></label><label>{$t("host.workspaceRoot")}<select bind:value={editWorkspaceRootId} onchange={()=>{pathBrowse=null;const base=roots.find(root=>root.id===editWorkspaceRootId)?.canonicalPath;if(base)editWorkspacePath=base;}}>{#each roots.filter(root=>root.allowRegister) as root}<option value={root.id}>{root.displayName}</option>{/each}</select></label><label class="wide">{$t("host.registeredPath")}<input bind:value={editWorkspacePath} maxlength="4096" autocomplete="off" spellcheck="false"/></label><div class="path-picker wide"><div><strong>{$t("host.folderTree")}</strong><button type="button" onclick={()=>browseWorkspacePath()}>{$t("host.browseFromRoot")}</button></div>{#if pathBrowse}<button type="button" class="current-dir" onclick={()=>{const selected=browsedCanonicalPath();if(selected)editWorkspacePath=selected;}}>{$t("host.selectThisFolder")} · {pathBrowse.current?.relativePath??"."}</button>{#each pathBrowse.entries??[] as entry}<button type="button" onclick={()=>browseWorkspacePath(entry.id)}>📁 {entry.name}</button>{/each}{:else}<small>{$t("host.pathHelp")}</small>{/if}</div></div><div class="workspace-actions"><button type="button" class="primary" onclick={()=>saveWorkspace(item)} disabled={!editWorkspaceName.trim()||!editWorkspacePath.trim()} aria-label={$t("host.saveNamed",{name:item.displayName})}><Save size={15}/></button><button type="button" onclick={cancelWorkspaceEdit} aria-label={$t("common.cancel")}><X size={15}/></button></div>{:else}<span><strong>{projects.find(project=>project.id===item.projectId)?.name??item.projectId} · {item.displayName}</strong><small title={item.canonicalPath}>{item.canonicalPath}</small><em>{item.lastGitStatus?.repository?`${item.lastGitStatus.branch??"detached"} · ${item.lastGitStatus.dirty?$t("host.changedFiles",{count:item.lastGitStatus.changedFiles?.length??"?"}):$t("workspace.noChanges")}${item.lastGitStatus.ahead||item.lastGitStatus.behind?` · ↑${item.lastGitStatus.ahead??0} ↓${item.lastGitStatus.behind??0}`:""}`:item.workspaceType}</em>{#if systemWorkspace(item)}<em class="system-badge"><Lock size={13}/>{$t("host.claudexWorkhouseWorkspaceLocked")}</em>{/if}</span><div class="workspace-actions"><button type="button" class:active={instructionWorkspace?.id===item.id} aria-expanded={instructionWorkspace?.id===item.id} aria-controls={`workspace-instructions-${item.id}`} onclick={()=>editInstructions(item)} aria-label={$t("workspace.instructionsFor",{name:item.displayName})}><BookOpenText size={15}/>{$t("workspace.instructions")}</button><button type="button" onclick={()=>onviewworkspace(item)} aria-label={$t("host.viewFiles",{name:item.displayName})}><Eye size={15}/></button><button type="button" onclick={()=>refreshGit(item)} aria-label={$t("host.checkGit",{name:item.displayName})}><RefreshCw size={15}/></button>{#if item.lastGitStatus?.repository && !systemWorkspace(item)}<button type="button" onclick={()=>createWorktree(item)} aria-label={$t("host.createWorktree",{name:item.displayName})}><GitBranch size={15}/></button>{/if}{#if !systemWorkspace(item)}<button type="button" onclick={()=>beginWorkspaceEdit(item)} aria-label={$t("host.editNamed",{name:item.displayName})}><Pencil size={15}/>{$t("common.edit")}</button><button type="button" class="workspace-remove" onclick={()=>unregisterWorkspace(item)} aria-label={$t("host.deleteWorkspace",{name:item.displayName})}><ArchiveX size={15}/>{$t("host.unregisterWorkspace")}</button>{/if}</div>{/if}{#if instructionWorkspace?.id===item.id}<aside id={`workspace-instructions-${item.id}`} class="instruction-panel" aria-label={$t("workspace.instructionsFor",{name:item.displayName})}>
    <header><span><strong>{item.displayName} · {$t("workspace.instructions")}</strong><small>{$t("workspace.instructionsBody")}</small></span><button type="button" onclick={()=>instructionWorkspace=null} aria-label={$t("common.close")}><X size={16}/></button></header>
    {#if instructionLoading}<p>{$t("common.loading")}</p>{:else}
      <div class="instruction-grid"><label class="check"><input type="checkbox" bind:checked={instructionProfile.enabled}/>{$t("workspace.instructionsEnabled")}</label><label class="check"><input type="checkbox" bind:checked={instructionProfile.agentEditable}/>{$t("workspace.instructionAgentEditable")}</label><label>{$t("workspace.instructionSources")}<select bind:value={instructionProfile.sourceMode}><option value="managed">{$t("workspace.sourceManaged")}</option><option value="repository">{$t("workspace.sourceRepository")}</option><option value="combined">{$t("workspace.sourceCombined")}</option></select></label><label>{$t("workspace.restartPolicy")}<select bind:value={instructionProfile.completionPolicy.restart}><option value="never">{$t("workspace.restartNever")}</option><option value="runtime-change">{$t("workspace.restartRuntime")}</option><option value="always">{$t("workspace.restartAlways")}</option></select></label><label>{$t("workspace.executionMode")}<select bind:value={instructionProfile.completionPolicy.execution}><option value="instruct">{$t("workspace.executeInstruct")}</option><option value="confirm">{$t("workspace.executeConfirm")}</option><option value="auto-safe">{$t("workspace.executeAutoSafe")}</option></select></label></div>
      <label class="instruction-markdown">{$t("workspace.instructionMarkdown")}<textarea bind:value={instructionProfile.markdown} maxlength="32768" rows="10" placeholder={$t("workspace.instructionPlaceholder")}></textarea></label>
      <div class="completion-checks"><label><input type="checkbox" bind:checked={instructionProfile.completionPolicy.requireCheck}/>{$t("workspace.requireCheck")}</label><label><input type="checkbox" bind:checked={instructionProfile.completionPolicy.requireTest}/>{$t("workspace.requireTest")}</label><label><input type="checkbox" bind:checked={instructionProfile.completionPolicy.requireBuild}/>{$t("workspace.requireBuild")}</label><label><input type="checkbox" bind:checked={instructionProfile.completionPolicy.requireDirectVerification}/>{$t("workspace.requireDirectVerification")}</label></div>
      <small class="policy-note">{$t("workspace.policyGuidanceOnly")}</small>
      <footer><small>{$t("workspace.instructionRevision",{revision:instructionProfile.revision})}{#if instructionProfile.lastEditedBy==="agent"}<span class="instruction-agent-edited" title={instructionProfile.lastEditedTaskId??undefined}>{$t("workspace.instructionEditedByAgent")}</span>{/if}{#if instructionRepository.length} · {instructionRepository.map(item=>item.name).join(", ")}{/if}</small><button type="button" class="primary" onclick={saveInstructions}><Save size={15}/>{$t("common.save")}</button></footer>
    {/if}
  </aside>{/if}</article>{/each}{#if !selectedHostWorkspaces.length}<p class="empty-small">{$t("host.noWorkspaces")}</p>{/if}</div>
  {#if notice}<p class="host-notice" aria-live="polite">{notice}</p>{/if}
</section>

<style>
  .host-settings{container-type:inline-size;display:grid;gap:.85rem}.section-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:.7rem}.section-heading h3{margin:0}.section-heading small{display:block;color:var(--muted);margin-top:.2rem}.section-heading button,.workspace-list button,.project-list button,.new-project-toggle{display:inline-flex;align-items:center;gap:.35rem}.workspace-context-heading{align-items:flex-start}.host-selector{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:.65rem;padding:.65rem;border:1px solid var(--line);border-radius:12px}.host-selector span{font-weight:700}.host-selector select{min-width:0}.workspace-actions,.project-actions{display:flex;gap:.5rem;flex-wrap:wrap}.danger-lite,.workspace-remove{color:var(--danger)}.workspace-remove{border-color:color-mix(in srgb,var(--danger) 45%,var(--line))}.workspace-actions button{white-space:nowrap}.project-heading,.workspace-heading{margin-top:.55rem}.new-project-toggle{justify-self:start}.project-form,.workspace-form{display:grid;grid-template-columns:1fr 1fr;gap:.65rem;padding:.8rem;border:1px solid var(--line);border-radius:14px}.project-form label,.workspace-form label{display:grid;gap:.3rem}.project-form .wide,.workspace-form .wide{grid-column:1/-1}.workspace-form .check{display:flex;align-items:center}.project-list,.workspace-list{display:grid;gap:.45rem}.project-list article,.workspace-list article{display:grid;grid-template-columns:1fr auto;align-items:center;gap:.6rem;padding:.65rem;border:1px solid var(--line);border-radius:12px}.workspace-list article{grid-template-columns:auto 1fr auto}.workspace-list article.editing{align-items:start}.project-list article.system-item,.workspace-list article.system-item{background:color-mix(in srgb,var(--panel) 88%,var(--accent) 12%)}.project-list article>span,.workspace-list article>span{min-width:0;display:grid;gap:.15rem}.project-list small,.workspace-list small{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.inline-edit{display:grid;grid-template-columns:minmax(140px,.7fr) minmax(180px,1.3fr);gap:.5rem}.inline-edit label{display:grid;gap:.2rem;font-size:.72rem;color:var(--muted)}.inline-edit .wide{grid-column:1/-1}.project-edit .pipeline-editor{grid-column:1/-1}.pipeline-editor,.path-picker{display:grid;gap:.4rem;padding:.55rem;border:1px solid var(--line);border-radius:10px;background:var(--bg)}.pipeline-editor>small,.path-picker>small{white-space:normal}.pipeline-editor>div{display:grid;grid-template-columns:1fr auto;align-items:center;gap:.45rem;padding:.4rem;border:1px solid var(--line);border-radius:8px}.pipeline-editor>div.selected{border-color:var(--accent)}.pipeline-editor>div>label{display:flex;align-items:center;gap:.5rem}.pipeline-editor>div>label>span{display:grid}.pipeline-order{display:flex!important;grid-auto-flow:column;align-items:center;gap:.25rem}.pipeline-order button{min-width:32px;justify-content:center}.pipeline-order em{min-width:1.4rem;text-align:center;font-style:normal;color:var(--accent)}.workspace-edit{grid-template-columns:1fr 1fr}.path-picker>div{display:flex;justify-content:space-between;align-items:center;gap:.5rem}.path-picker>button{text-align:left;justify-content:flex-start}.path-picker>.current-dir{border-color:var(--accent)}.system-badge{display:inline-flex!important;align-items:center;gap:.25rem;width:max-content;font-style:normal!important;font-size:.72rem!important;color:var(--accent)!important}.workspace-list em{font-style:normal;color:var(--muted);font-size:.78rem}.empty-small,.host-notice{color:var(--muted);margin:.2rem}.host-notice{color:var(--warn)}
  .workspace-project-summary{display:flex;gap:.4rem;overflow-x:auto;padding:.15rem 0;scrollbar-width:none}.workspace-project-summary span{flex:none;padding:.35rem .55rem;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:.72rem}.workspace-project-summary span:not(.missing){border-color:color-mix(in srgb,var(--accent) 45%,var(--line));color:var(--text)}.workspace-project-summary span.missing{color:var(--danger)}
  .github-picker{display:grid;gap:.35rem}.github-picker>div{display:flex;gap:.4rem}.github-picker input{flex:1}
  .field-error{color:var(--danger)!important;white-space:normal!important}
  .workspace-actions button.active{border-color:var(--accent);color:var(--accent)}.workspace-list article>.instruction-panel{grid-column:1/-1;width:100%;box-sizing:border-box}.instruction-panel{display:grid;gap:.75rem;padding:.8rem;border:1px solid color-mix(in srgb,var(--accent) 55%,var(--line));border-radius:14px;background:var(--panel)}.instruction-panel header,.instruction-panel footer{display:flex;align-items:center;justify-content:space-between;gap:.7rem}.instruction-panel header span{display:grid;gap:.2rem}.instruction-panel header small,.instruction-panel footer small,.policy-note{color:var(--muted)}.instruction-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.55rem}.instruction-grid label,.instruction-markdown{display:grid;gap:.3rem;font-size:.78rem;color:var(--muted)}.instruction-grid .check{display:flex;align-items:center}.instruction-markdown textarea{width:100%;resize:vertical;line-height:1.45;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.completion-checks{display:flex;gap:.7rem;flex-wrap:wrap}.completion-checks label{display:flex;align-items:center;gap:.25rem;font-size:.78rem}.instruction-panel footer button{display:inline-flex;align-items:center;gap:.35rem}.instruction-agent-edited{display:inline-flex;margin-left:.4rem;padding:.15rem .4rem;border:1px solid color-mix(in srgb,var(--amber) 45%,var(--line));border-radius:999px;background:color-mix(in srgb,var(--amber) 10%,var(--panel));color:var(--amber);font-weight:700}
  @media(max-width:600px){.section-heading{align-items:stretch;flex-direction:column}.section-heading>button{min-height:44px;justify-content:center}.host-selector{grid-template-columns:1fr}.project-form,.workspace-form,.inline-edit,.instruction-grid{grid-template-columns:1fr}.project-form .wide,.workspace-form .wide{grid-column:auto}.project-list article,.workspace-list article{min-height:56px}.project-actions,.workspace-actions{justify-content:flex-end}.host-settings{padding-bottom:calc(env(safe-area-inset-bottom) + .5rem)}}
  @container(max-width:650px){.workspace-list article{grid-template-columns:auto minmax(0,1fr)}.workspace-list article>.workspace-actions{grid-column:1/-1;justify-content:flex-end}.workspace-edit{grid-template-columns:1fr}.workspace-edit .wide{grid-column:auto}}
</style>
